import{_ as t,b as e,c as a,g as n}from"./chunks/framework.86O3EbG5.js";const h=JSON.parse('{"title":"微前端架构与实践概述","description":"","frontmatter":{"title":"微前端架构与实践概述","tags":["Programming Design"],"author":"oasis"},"headers":[],"relativePath":"articles/frontend/micro-frontends/1.md","filePath":"articles/frontend/micro-frontends/1.md"}'),o={name:"articles/frontend/micro-frontends/1.md"};function l(r,i,d,s,_,p){return e(),a("div",null,[...i[0]||(i[0]=[n('<h2 id="什么是微前端" tabindex="-1">什么是微前端</h2><p>一种将可独立交付的前端应用程序组合成一个更大的整体的架构风格。这里强调是一种架构风格。</p><h2 id="微前端解决什么问题" tabindex="-1">微前端解决什么问题</h2><ol><li>更小、更内聚且可维护的代码库</li><li>从组织角度来看，可实现团队自治</li><li>更增量的升级、更新甚至重写前端部分的能力</li><li>可以避免大型单体仓库，减少更多的冲突</li></ol><h2 id="如何拆分微前端" tabindex="-1">如何拆分微前端</h2><p>通过应用程序的限界上下文进行拆分</p><h2 id="实践方案" tabindex="-1">实践方案</h2><h3 id="_1-后端组合" tabindex="-1">1. 后端组合</h3><p>主要通过后端模板配合服务器配置进行拼合</p><h3 id="_2-前端组合" tabindex="-1">2. 前端组合</h3><ol><li>通过 iframe 进行运行时集成</li><li>通过 JavaScript 进行运行时集成</li><li>通过 Web Components 进行运行时集成</li></ol><p>iframe 具有天然的隔离性，保证 JS 和 CSS 不会产生冲突。其他前端运行时方案需要考虑 JS 和 CSS 的冲突处理，shadow DOM 提供了良好的样式隔离。</p><h2 id="实现方案概述" tabindex="-1">实现方案概述</h2><ol><li>构建基座应用，用来管理微前端的加载</li><li>通过路由匹配，处理微前端的资源进行加载执行</li></ol>',14)])])}const m=t(o,[["render",l]]);export{h as __pageData,m as default};
